-- Zone Control launch seed (2026-09-04): the four shard-store rows the new build reads at start.
-- Runs after 2026-09-02-00-ZoneControl-Store-Value-MediumText.sql (file-name order), so the value column is
-- already MEDIUMTEXT; the zonecontrol_data row is 77,350 bytes and would not fit TEXT.
-- INSERT IGNORE: seeds a key only when it is absent. A server that already carries a store keeps its own.
-- Rows: zonecontrol_data (zones Tou Tou / Neftlet / Tou Tou 12 / Tou Tou 13 + tier defaults 11-25),
-- weaponscaling_data (weapon scaling ON + tier rows + grade ladders), craftgate_data, nolog_landblocks.
INSERT IGNORE INTO `config_properties_string` VALUES ('craftgate_data','{\"Components\":[21037,21039,21048,21054,21056,21064,21069,21079,21081,21085,21086,29571,29572,29574,29577,29578,29580,30094,30095,30097,30099,30100,30102,30103,30104,30260,36619,36620,36622,36624,36625,36626,36627,36628,60000,300011,3110315,64454645,227190065,527870013,527870019,527870020,527870021,527870022,527870023,527870024,527870031,719220045,719220085]}','T11+ crafting gate matrix (JSON)');
INSERT IGNORE INTO `config_properties_string` VALUES ('nolog_landblocks','654C:all','Overrides for the no-log landblock list (log out here, log back in at your lifestone). Comma-separated tokens, each [-]HEX[:base|all|<variation>] - e.g. \"016C:11, 0007:all, -0002\". A bare token or one starting \'+\' ADDS; one starting \'-\' SUPPRESSES, including entries from the built-in retail list. Variation omitted means base only; \'all\' means base and every variation. Edit with /nolog rather than by hand.');
